    categories:["India","South Asia","Successor states","British Commonwealth","GEACPS","Princely states"],facts:[["Collapse of the Raj","1948–1949 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["British doctrine","Bastion India · 1949–1952 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Proxy high tide","1952–1956 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Colombo Armistice System","1958–1961 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Long-war condition","After 1965 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Principal all-India claimants","Congress India · Hindustan · Azad Hind <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Principal strategic patrons","Britain · Japan <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Western consolidation","Kalat victory · 1981–1984 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Hyderabad association","Japan · 1986 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["British mainland position","Southern and western treaty partners <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Japanese mature strategy","Azad Hind eastern blocker · Hyderabad princely gateway <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Common foreign settlement medium","American gold dollar <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Unified citizenship","Absent <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Unified Indian state","Absent <sup class='canon-note' data-provenance='a'>[a]</sup>"]]
